  [120] = { "I bersagli in un cono davanti all'incantatore subiscono $N1 danni da gelo e sono rallentati del $N2% per $D1. I primi $N4 bersagli colpiti dal cono sono rallentati di un ulteriore $N5% per altri $D2.", "Velocità di movimento ridotta del $N1%.", 0x0c47ae4d, 0xbe1d3d24, "uu" },
