  [635] = { "Cura un bersaglio alleato di $N1.", nil, 0xbe4c0f4a, nil, "um" },
  [639] = { "Cura un bersaglio alleato di $N1.", nil, 0xbe4c0f4a, nil, "um" },
  [642] = { "Protegge il Paladino da tutti i danni e gli incantesimi per $D1, ma riduce del $N2% tutti i danni che infliggi. Applica Rigorosità per $D2. Non può essere lanciato mentre Rigorosità è attiva.", "Immune ad attacchi e incantesimi, ma tutti i danni che infliggi sono ridotti del $N1%.", 0x0bcdb662, 0x69b0b050, "uu" },
  [643] = { "Fornisce $N1 Armatura aggiuntiva ai membri del gruppo entro $N2 m. Il bersaglio alleato può ricevere solo un'Aura per Paladino alla volta.", "Armatura aumentata di $N1.", 0xc600442a, 0xa12a98e7, "uu" },
  [647] = { "Cura un bersaglio alleato di $N1.", nil, 0xbe4c0f4a, nil, "um" },
  [674] = { "Permette di equipaggiare nella mano secondaria una qualsiasi arma a una mano.", nil, 0x8a696461, nil, "um" },
  [676] = { "Disarma il nemico per $D1.", "Disarmato!", 0xef69889f, 0x98985ecd, "uu" },
  [686] = { "Lancia un dardo d'ombra contro il nemico, infliggendo $N1 danni da ombra.", nil, 0xc6f8d47d, nil, "um" },
  [687] = { "Protegge l'incantatore, aumentando l'Armatura di $N1 e rigenerando $N2 salute in più ogni $D1 per $D2.", "Armatura aumentata di $N1 e $N2 salute in più rigenerata ogni $D1.", 0xb698fcaa, 0xd002df12, "uu" },
  [688] = { "Evoca un imp agli ordini dello Stregone.", nil, 0xe09ab690, nil, "um" },
  [689] = { "Trasferisce $N1 salute ogni $N2 s dal bersaglio all'incantatore. Dura $D1.", "Risucchia $N1 salute ogni $N2 s a favore dell'incantatore.", 0xc595b3f3, 0x66d948fc, "uu" },
  [691] = { "Evoca un vilsegugio agli ordini dello Stregone.", nil, 0xa4f630d4, nil, "um" },
  [693] = { "Crea una Pietra dell'Anima Minore. La Pietra dell'Anima può essere usata per custodire l'anima di un bersaglio. Se il bersaglio muore mentre la sua anima è custodita, potrà resuscitare con $N1 salute e $N2 mana.\n\nGli oggetti evocati scompaiono se si resta disconnessi per più di $N3 min.", nil, 0x2d3cf636, nil, "um" },
  [694] = { "Un attacco beffardo che infligge $N1 danni, genera una moderata quantità di minaccia e costringe il bersaglio a concentrare i suoi attacchi su di te per $D1.", "Provocato.", 0x8506dcc4, 0x36f56123, "uu" },
  [695] = { "Lancia un dardo d'ombra contro il nemico, infliggendo $N1 danni da ombra.", nil, 0xc6f8d47d, nil, "um" },
  [696] = { "Protegge l'incantatore, aumentando l'Armatura di $N1 e rigenerando $N2 salute in più ogni $D1 per $D2.", "Armatura aumentata di $N1 e $N2 salute in più rigenerata ogni $D1.", 0xb698fcaa, 0xd002df12, "uu" },
  [697] = { "Evoca un'ombra del Vuoto agli ordini dello Stregone.", nil, 0xe766a608, nil, "um" },
  [698] = { "Avvia un rituale che evoca il membro del gruppo bersaglio. Per completare il rituale servono l'incantatore e altri $N1 membri del gruppo. Per partecipare, tutti i giocatori devono essere fuori dal combattimento, cliccare con il tasto destro sul portale e non muoversi finché il rituale non è completo.", nil, 0x243b7c43, nil, "um" },
  [699] = { "Trasferisce $N1 salute ogni $N2 s dal bersaglio all'incantatore. Dura $D1.", "Risucchia $N1 salute ogni $N2 s a favore dell'incantatore.", 0xc595b3f3, 0x66d948fc, "uu" },
  [700] = { nil, "Addormentato.", nil, 0x5339954e, "mu" },
  [702] = { "I danni fisici inflitti dal bersaglio sono ridotti di $N1 per $D1. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Danni fisici inflitti ridotti di $N1.", 0x45b27a1b, 0x21281ce3, "uu" },
  [703] = { "Strangola il nemico con una garrota, infliggendo $N1 danni in $D1, aumentati dalla tua potenza d'attacco. Devi essere in modalità furtiva e dietro al bersaglio. Fornisce $N3 punti combo.", "$N1 danni subiti ogni $N2 s.", 0xdd3a1872, 0xef5a123f, "uu" },
  [704] = { "Maledice il bersaglio con l'avventatezza, riducendo la sua Armatura di $N1 per $D1. I nemici maledetti non fuggono e ignorano gli effetti di paura e di orrore. Su un bersaglio può essere attiva solo una maledizione per Stregone alla volta.", "Armatura ridotta di $N1. Il bersaglio non fugge e ignora gli effetti di paura e di orrore.", 0x543f2e0b, 0x7af54e1d, "uu" },
  [705] = { "Lancia un dardo d'ombra contro il nemico, infliggendo $N1 danni da ombra.", nil, 0xc6f8d47d, nil, "um" },
  [706] = { "Protegge l'incantatore, aumentando l'Armatura di $N1 e la resistenza all'ombra di $N2 e rigenerando $N3 salute in più ogni $D1 per $D2.", "Armatura aumentata di $N1, resistenza all'ombra aumentata di $N2 e $N3 salute in più rigenerata ogni $D1.", 0x6ab340ac, 0x91ee7074, "uu" },
  [707] = { "Brucia il nemico, infliggendo $N1 danni da fuoco e altri $N2 danni da fuoco in $D1.", "$N1 danni da fuoco ogni $N2 s.", 0xe3931f57, 0x0d35ca56, "uu" },
  [709] = { "Trasferisce $N1 salute ogni $N2 s dal bersaglio all'incantatore. Dura $D1.", "Risucchia $N1 salute ogni $N2 s a favore dell'incantatore.", 0xc595b3f3, 0x66d948fc, "uu" },
  [710] = { "Esilia il nemico bersaglio, impedendogli di compiere qualsiasi azione ma rendendolo invulnerabile per un massimo di $D1. Può essere esiliato solo un bersaglio alla volta. Funziona solo su demoni ed elementali.", "Invulnerabile, ma impossibilitato ad agire.", 0x655db914, 0xb1a1673e, "uu" },
  [712] = { "Evoca una succube agli ordini dello Stregone.", nil, 0x7284109d, nil, "um" },
  [724] = { "Crea un Pozzo di Luce sacro vicino al Sacerdote. I membri della tua incursione o del tuo gruppo possono cliccare sul Pozzo di Luce per rigenerare $N1 salute in $D1. Subire un attacco annulla l'effetto. Il Pozzo di Luce dura $D2 o $N4 cariche.", nil, 0x3bb13606, nil, "um" },
  [740] = { "Cura tutti i membri del gruppo vicini entro $N1 m di $N2 ogni $D1 per $D2. Il Druido deve mantenere la canalizzazione affinché l'incantesimo resti attivo.", "Cura i membri del gruppo vicini di $N1 ogni $D1.", 0x96808906, 0x80aae398, "uu" },
  [744] = { "Infligge danni da natura a un nemico ogni $N1 s per $D2.", "Danni da natura inflitti ogni $N1 s.", 0x05ece599, 0xaf62b13e, "uu" },
  [745] = { "Lancia una ragnatela contro il nemico, immobilizzandolo per $D1.", "Immobilizzato.", 0xc19c3572, 0x18deeb81, "uu" },
  [746] = { "Cura di $N1 in $D1.", "$N1 salute rigenerata ogni $N2 s.", 0xcb31688f, 0x4b6eb5c1, "uu" },
  [755] = { "Fornisce $N1 salute al famiglio dell'incantatore ogni secondo per $D1, finché l'incantatore canalizza. Genera una minaccia ridotta.", { "Trasferimento di vita in corso. Generazione di minaccia aumentata del $N1%.", "Trasferimento di vita in corso.", shape = { "1/0", "0/0" } }, 0x0aeefa60, 0xe55a3f4d, "uu" },
  [759] = { "Evoca un'Agata di Mana che può essere usato per rigenerare istantaneamente $N1 mana.\n\nGli oggetti evocati scompaiono se si resta disconnessi per più di $N2 min.", nil, 0xf55fa5a2, nil, "um" },
  [768] = { "Assume la ⟦Cat Form=Forma Felina⟧, aumentando la potenza d'attacco di $N1 più l'Agilità. Inoltre protegge l'incantatore dagli effetti di metamorfosi e permette di usare varie abilità feline.\n\nIl cambio di forma libera l'incantatore dagli effetti di metamorfosi e di limitazione al movimento.", "Immune agli effetti di metamorfosi. Potenza d'attacco aumentata di $N1 più l'Agilità.", 0xc11c18e5, 0xe61e1ebc, "uu" },
  [769] = { "Sferra una spazzata contro $N1 nemici vicini, infliggendo $N2 danni.", nil, 0xb0c704b4, nil, "um" },
  [770] = { "Riduce l'Armatura del bersaglio di $N1 per $D1. Mentre ne è affetto, il bersaglio non può entrare in modalità furtiva o diventare invisibile.", "Armatura ridotta di $N1. Impossibile entrare in modalità furtiva o diventare invisibile.", 0xf183631b, 0xa06fedc8, "uu" },
  [772] = { "Ferisce il bersaglio facendolo sanguinare, infliggendo $N1 danni in $D1.", "$N1 danni da sanguinamento subiti ogni $N2 s.", 0x47f171f5, 0xbabe73bb, "uu" },
  [774] = { "Cura il bersaglio di $N1 in $D1.", "Cura di $N1 ogni $N2 s.", 0x3367b9a9, 0x1302c045, "uu" },
  [775] = { "Trasforma il Druido in un albero, rimuovendo tutti gli effetti fisici dannosi e proteggendolo da tutti gli attacchi fisici per $D1, ma in questo periodo non puoi attaccare, muoverti né lanciare incantesimi. Inoltre protegge l'incantatore dagli effetti di metamorfosi.\n\nIl cambio di forma libera l'incantatore dagli effetti di immobilizzazione, rallentamento e congelamento.", "Immune a tutti gli attacchi fisici e agli effetti di metamorfosi. Impossibile attaccare, muoversi o lanciare incantesimi.", 0x85f18425, 0x96e3dd30, "uu" },
  [778] = { "Riduce l'Armatura del bersaglio di $N1 per $D1. Mentre ne è affetto, il bersaglio non può entrare in modalità furtiva o diventare invisibile.", "Armatura ridotta di $N1. Impossibile entrare in modalità furtiva o diventare invisibile.", 0xf183631b, 0xa06fedc8, "uu" },
  [779] = { "Sferra una spazzata contro $N1 nemici vicini, infliggendo $N2 danni.", nil, 0xb0c704b4, nil, "um" },
  [780] = { "Sferra una spazzata contro $N1 nemici vicini, infliggendo $N2 danni.", nil, 0xb0c704b4, nil, "um" },
  [781] = { "Tenta di disimpegnarsi dal bersaglio riducendo la minaccia. Disattiva l'attacco automatico.", nil, 0x30340e84, nil, "um" },
  [782] = { "Delle spine fuoriescono dal bersaglio alleato, infliggendo $N1 danni da natura agli attaccanti quando colpiscono. Dura $D1.", "Infligge $N1 danni da natura agli attaccanti.", 0xda837ee9, 0x763a853a, "uu" },
  [783] = { "Assume la ⟦Travel Form=Forma Celere⟧, aumentando la velocità di movimento del $N1%. Inoltre protegge l'incantatore dagli effetti di metamorfosi. Utilizzabile solo all'aperto.\n\nIl cambio di forma libera l'incantatore dagli effetti di metamorfosi e di limitazione al movimento.", "Immune agli effetti di metamorfosi. Velocità di movimento aumentata del $N1%.", 0x3c4fa632, 0x71489b20, "uu" },
  [785] = { nil, "Ammaliato.\nDanni aumentati del $N1%.\nIncantesimi istantanei.\nResistenze aumentate di $N2.\nVelocità di movimento aumentata del $N3%.", nil, 0x7c6c4777, "mu" },
