  [835] = { nil, "Stordito.", nil, 0x27f95286, "mu" },
  [837] = { "Lancia un dardo di gelo contro il nemico, infliggendo $N1 danni da gelo e riducendo la sua velocità di movimento del $N2% per $D1.", "Velocità di movimento ridotta del $N1%.", 0x0ea2143b, 0xbe1d3d24, "uu" },
