  [945] = { "L'incantatore è circondato da $N1 sfere di fulmini. Quando un incantesimo o un attacco in mischia o a distanza colpisce l'incantatore, l'attaccante subisce $N2 danni da natura. Ogni colpo consuma una sfera di fulmini. Non più di una sfera colpisce ogni qualche secondo. Dura $D1.", "$N1 danni da natura inflitti agli attaccanti all'impatto.", 0x2bdc4806, 0x0a4ee6cf, "uu" },
